using Microsoft.AspNetCore.Mvc;using RaceDay.MVC.Services;using RaceDay.MVC.Security;
namespace RaceDay.MVC.Controllers;[RequireRole("Participant")]public class ParticipantController(ApiService api):Controller{public async Task<IActionResult>Index(){ViewBag.Events=await api.GetAsync<List<Dictionary<string,object>>>("api/events")??[];ViewBag.Enrolments=await api.GetAsync<List<Dictionary<string,object>>>("api/enrolments")??[];ViewBag.Results=await api.GetAsync<List<Dictionary<string,object>>>("api/results")??[];return View();}public async Task<IActionResult>MyEvents()=>View(await api.GetAsync<List<Dictionary<string,object>>>("api/enrolments")??[]);public async Task<IActionResult>MyResults()=>View(await api.GetAsync<List<Dictionary<string,object>>>("api/results")??[]);}
